                [A[1][0]*B[0][0] + A[1][1]*B[1][0], A[1][0]*B[0][1] + A[1][1]*B[1][1]]]
    def mat_pow(M, p):
        result = [[1, 0], [0, 1]]
        while p > 0:
            if p % 2 == 1:
                result = mat_mult(result, M)
            M = mat_mult(M, M)
            p //= 2
        return result
