def longest_unique_substring(s: str) -> int:
    # This implementation is intentionally simple and not O(n)
    longest = 0
    n = len(s)
    for i in range(n):
        seen = set()
        for j in range(i, n):
            if s[j] in seen:
                break
            seen.add(s[j])
            longest = max(longest, j - i + 1)
    return longest

